y Bait\", {\n            Name = \"Auto Buy Bait\",\n            Default = false,\n            Callback = function(value)\n                MiscFlags.AutoBuy = value\n                if value then\n                    NexusLib:Notify({ Title = \"Auto Buy\", Message = \"[ON] Buy \" .. NexusState.buyBaitQuantity .. \" \" .. NexusState.selectedBait .. \" when below \" .. NexusState.buyBaitThreshold, Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Auto Buy\", Message = \"OFF\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Buy Bait\", {\n            Name = \"Auto Buy Bait\",\n            Default = false,\n            Callback = function(value)\n                MiscFlags.AutoBuy = value\n                if value then\n                    NexusLib:Notify({ Title = \"Auto Buy\", Message = \"[ON] Buy \" .. NexusState.buyBaitQuantity .. \" \" .. NexusState.selectedBait .. \" when below \" .. NexusState.buyBaitThreshold, Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Auto Buy\", Message = \"OFF\", Duration = 2 })\n                end\n            end\n        })\n\n        task.spawn(function()\n            local lastBuyTick = 0\n            while task.wait(1) do\n                if not alive() then break end\n                if MiscFlags.AutoBuy and (tick() - lastBuyTick) > 3 then\n                    local baitName = NexusState.selectedBait\n                    local qty = NexusState.buyBaitQuantity\n                    local threshold = NexusState.buyBaitThreshold\n                    if baitName ~= \"No bait available\" then\n                        local count = -1\n                        pcall(function()\n                            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                            if not userData then return end\n                            local baitFolder = userData:FindFirstChild(\"Bait\")\n                            if not baitFolder then return end\n                            local bait = baitFolder:FindFirstChild(baitName)\n                            if bait and typeof(bait) == \"Instance\" and (bait:IsA(\"NumberValue\") or bait:IsA(\"IntValue\")) then\n                                count = bait.Value\n                            end\n                        end)\n                        if count >= 0 and count < threshold then\n                            lastBuyTick = tick()\n                            local baitMerchant = findBaitMerchantHRP()\n                            local char = LocalPlayer.Character\n                            local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n                            local origCFrame = root and root.CFrame\n\n                            if baitMerchant and root then\n                                root.CFrame = CFrame.new(baitMerchant.Position + Vector3.new(0, 2, 0))\n                                task.wait(0.15)\n                            end\n\n                            pcall(function()\n                                Events.BuyBait:FireServer(baitName, qty)\n                            end)\n\n                            if origCFrame and root then\n                                task.wait(0.15)\n                                root.CFrame = origCFrame\n                            end\n\n                            NexusLib:Notify({\n                                Title = \"Auto Buy\",\n                                Message = baitName .. \": \" .. count .. \" left - bought \" .. qty,\n                                Duration = 2\n                            })\n                        end\n                    end\n                end\n            end\n        end)\n    end\n\n    -- Auto Buy Rod\n    do\n        local RodSection = ShopTab:CreateSection(\"Auto Buy Rod\")\n        local function GetBuyableRods()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {\"No rod available\"} end\n            local rods = {}\n            local inv = p:FindFirstChild(\"FishingRodInventory\")\n            if not inv then return {\"No rod available\"} end\n            for _, rodFolder in pairs(inv:GetChildren()) do\n                if typeof(rodFolder) == \"Instance\" and typeof(rodFolder) == \"Instance\" and rodFolder:IsA(\"Folder\") then\n                    local owned = rodFolder:FindFirstChild(\"Owned\")\n                    if owned and owned.Value == false then\n                        local mod = Info and Info.Inventory and Info.Inventory:FindFirstChild(rodFolder.Name)\n                        if mod then\n                            table.insert(rods, rodFolder.Name)\n                        end\n                    end\n                end\n            end\n            if #rods == 0 then return {\"No rod available\"} end\n            return rods\n        end\n\n        local buyableRods = GetBuyableRods()\n        local selectedRod = buyableRods[1] or \"No rod available\"\n\n        local rodDropdown = Cfg.register(RodSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Rod to Buy\", {\n            Name = \"Select Rod to Buy\",\n            Options = buyableRods,\n            Default = selectedRod,\n            Callback = function(value) selectedRod = value end\n        })), \"Dropdown\", \"Select Rod to Buy\", {\n            Name = \"Select Rod to Buy\",\n            Options = buyableRods,\n            Default = selectedRod,\n            Callback = function(value) selectedRod = value end\n        })\n\n        local buyRodMethodDropdown = Cfg.register(RodSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Buy Method\", {\n            Name = \"Buy Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.buyRod.method or \"Instant\",\n            Callback = function(value) NexusState.buyRod.method = value end\n        })), \"Dropdown\", \"Buy Method\", {\n            Name = \"Buy Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.buyRod.method or \"Instant\",\n            Callback = function(value) NexusState.buyRod.method = value end\n        })\n\n        RodSection:CreateButton({\n            Name = \"Buy Selected Rod\",\n            Callback = function()\n                if selectedRod == \"No rod available\" then\n                    NexusLib:Notify({ Title = \"Buy Rod\", Message = \"No rod available to buy\", Duration = 2 })\n                    return\n                end\n                NexusState.buyRod.teleported = false\n                NexusState.buyRod.oldPosition = nil\n                if NexusState.buyRod.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local buyFishingRod = npc:FindFirstChild(\"BuyFishingRod\")\n                        if buyFishingRod then\n                            local biaoDi = buyFishingRod:FindFirstChild(\"Biao Di\")\n                            if typeof(biaoDi) == \"Instance\" and biaoDi:IsA(\"Model\") then\n                                local hrp = biaoDi:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.buyRod.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.buyRod.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.buyRod.teleported then\n                        NexusLib:Notify({ Title = \"Buy Rod\", Message = \"Could not find Biao Di, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n                pcall(function()\n                    Events.BuyFishingRod:FireServer(selectedRod)\n                    NexusLib:Notify({ Title = \"Buy Rod\", Message = \"Bought \" .. selectedRod, Duration = 2 })\n                end)\n                if NexusState.buyRod.teleported and NexusStan return handle end\n        local kind = cfgKind(callKind)\n        local entry = ConfigSys.registry[name]\n        if not entry then\n            entry = { kind = kind }\n            ConfigSys.registry[name] = entry\n            table.insert(ConfigSys.ordered, name)\n        end\n        entry.kind = kind\n        -- The original Callback is captured here at registration time (from the\n        -- config table), because NexusLib handles do not expose it.\n        local cb = config and config.Callback or nil\n        if type(handle.Get) == \"function\" then\n            entry.get = function()\n                local ok, v = pcall(handle.Get)\n                return ok and v or nil\n            end\n        end\n        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set\n        -- calls set(v, false); dropdown/text Set only touch the label). After\n        -- Set we therefore re-fire the captured Callback so the hub state\n        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.\n        if type(handle.Set) == \"function\" then\n            entry.set = function(v)\n                pcall(handle.Set, handle, v)\n                if cb then\n                    task.spawn(cb, v)\n                end\n            end\n        elseif cb then\n            entry.set = function(v)\n                task.spawn(cb, v)\n            end\n        end\n        return handle\n    end\n\n    function ConfigSys.snapshot()\n        local out = {}\n        for name, entry in pairs(ConfigSys.registry) do\n            if entry.get then\n                local ok, v = pcall(entry.get)\n                if ok and v ~= nil then out[name] = v end\n            end\n        end\n        return out\n    end\n\n    function ConfigSys.apply(data)\n        if type(data) ~= \"table\" then return 0, 0 end\n        local okCount, missCount = 0, 0\n        for name, value in pairs(data) do\n            local entry = ConfigSys.registry[name]\n            if entry and entry.set then\n                local ok = pcall(entry.set, value)\n                if ok then okCount = okCount + 1 else missCount = missCount + 1 end\n            else\n                missCount = missCount + 1\n            end\n        end\n        return okCount, missCount\n    end\n\n    local function encode(data)\n        local HttpService = Services.HttpService\n        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)\n        return ok and s or nil\n    end\n\n    local function decode(s)\n        local HttpService = Services.HttpService\n        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)\n        if ok and type(data) == \"table\" then return data end\n        return nil\n    end\n\n    function ConfigSys.save(slot)\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Encode failed.\", Duration = 3 })\n            return false\n        end\n        if not writefile then\n            NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n            return false\n        end\n        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)\n        NexusLib:Notify({ Title = \"Config\", Message = ok and \"Saved.\" or \"Save failed.\", Duration = 2 })\n        return ok\n    end\n\n    function ConfigSys.load(slot, silent)\n        if not (isfile and readfile) then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot read files.\", Duration = 3 }) end\n            return false\n        end\n        local path = slot or ConfigSys.FILE\n        local has = false\n        pcall(function() has = isfile(path) end)\n        if not has then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"No saved config found.\", Duration = 3 }) end\n            return false\n        end\n        local ok, raw = pcall(readfile, path)\n        if not ok or not raw then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Read failed.\", Duration = 3 }) end\n            return false\n        end\n        local wrap = decode(raw)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Config file is corrupt.\", Duration = 3 }) end\n            return false\n        end\n        -- Defer one frame so every tab has finished building its controls.\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            if not silent then\n                NexusLib:Notify({ Title = \"Config\", Message = \"Loaded \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n            end\n        end)\n        return true\n    end\n\n    function ConfigSys.exportCode()\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then return nil end\n        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard\n        if clip then\n            pcall(clip, payload)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Config code copied to clipboard.\", Duration = 3 })\n        else\n            NexusLib:Notify({ Title = \"Config\", Message = \"Clipboard not supported on this executor.\", Duration = 3 })\n        end\n        return payload\n    end\n\n    -- Import reads the clipboard when the executor exposes it; otherwise it falls\n    -- back to the textbox value typed/pasted by the user.\n    function ConfigSys.importCode(text)\n        local code = text\n        if (not code or code == \"\") and getclipboard then\n            pcall(function() code = getclipboard() end)\n        end\n        if not code or code == \"\" then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Paste a config code first.\", Duration = 3 })\n            return false\n        end\n        local wrap = decode(code)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Invalid config code.\", Duration = 3 })\n            return false\n        end\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Imported \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n        end)\n        return true\n    end\n\n    runtimeEnv.NexusConfig = ConfigSys\n    runtimeEnv.NexusCfgWrap = ConfigSys.wrap\n    ConfigSys._saving = false\nend\n\n\nlocal Cfg = runtimeEnv.NexusConfig\n\n-- ===== HOME TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage(\"dung UI: Session tab\")\n    local HomeTab\n    do\n        local ok, result = pcall(function() return Window:CreateTab(\"Session\") end)\n        if not ok or result == nil then\n            runtimeEnv.NexusStage(\"UI Session tab failed\")\n            runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateTab Session: \" .. tostring(result))\n            return\n        end\n        HomeTab = result\n    end\n    HomeTab:CreateHeader({\n        Title = \"Session overview\",\n        Subtitle = \"Live instruments for \" .. LocalPlayer.Name\n    })\n    local statRow = HomeTab:CreateStatRow({\n        {Title = \"LEVEL\", Value = \"...\", Color = Color3.fromRGB(190, 158, 103)},\n        {Title = \"BALANCE\", Value = \"...\", Color = Color3.fromRGB(128, 159, 164)},\n        {Title = \"SESSION\", Value = \"00:00:00\", Color = Color3.fromRGB(139, 161, 142)}\n    })\n        -- Add 9 new stats\n    local statRow2 = HomeTab:CreateStatRow({\n        {Title = \"ROD\", Value = \"...\", Color = Color3.fromRGB(255, 215, 0)},\n        {Title = \"CRYSTAL\", Value = \"...\", Color = Color3.fromRGB(100, 200, 255)},\n        {Title = \"ESSENCE\", Value = \"...\", Color = Color3.fromRGB(255, 100, 200)}\n    })\n    local statRow3 = HomeTab:CreateStatRow({\n        {Title = \"BAIT\", Value = \"...\", Color = Color3.fromRGB(150, 255, 150)},\n        {Title = \"FISH CAUGHT\", Value = \"...\", Color = Color3.fromRGB(255, 200, 100)},\n        {Title = \"TICKET\", Value = \"...\", Color = Color3.fromRGB(200, 150, 255)}\n    })\n    local statRow4 = HomeTab:CreateStatRow({\n        {Title = \"TRAIT REROLL\", Value = \"...\", Color = Color3.fromRGB(255, 150, 150)},\n        {Title = \"HEAVIEST FISH\", Value = \"...\", Color = Color3.fromRGB(255, 180, 50)},\n        {Title = \"BASE HP\", Value = \"...\", Color = Color3.fromRGB(255, 100, 100)}\n    })\n    local hwid = \"N/A\"\n    pcall(function() hwid = Services.RbxAnalyticsService:GetClientId() end)\n    HomeTab:CreateFeaturedCard({\n        Tag = \"Nexus\",\n        Title = \"Heavyweight Fishing\",\n        Description = \"Script by: Ngmankhoi,NgdepZaiNhatTG,Ethangcuto\\n\\nHWID: \" .. string.sub(hwid, 1, 15) .. \"...\",\n        ButtonText = \"DISCORD\",\n        Callback = function()\n            NexusLib:Notify({ Title = \"Discord\", Message = \"Link copied to clipboard!\", Duration = 3 })\n            if setclipboard then setclipboard(\"https://discord.gg/QAdVUX2wCH\") end\n        end\n    })\n\n        local scriptStartTime = time()\n        task.spawn(function()\n        -- Cache for every stat row\n        local cachedStat1, cachedStat2, cachedStat3\n        local cachedStat2_1, cachedStat2_2, cachedStat2_3\n        local cachedStat3_1, cachedStat3_2, cachedStat3_3\n        local cachedStat4_1\n        local cachedStat4_2, cachedStat4_3\n        local labelCache = {}\n\n        local function setStat(statFrame, text)\n            if not statFrame then return end\n            local lbl = labelCache[statFrame]\n            if not lbl or not lbl.Parent then\n                for _, child in ipairs(statFrame:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"TextLabel\") and child.TextSize >= 18 then\n                        lbl = child\n                        labelCache[statFrame] = child\n                        break\n                    end\n                end\n            end\n            if lbl and lbl.Text ~= text then lbl.Text = text end\n        end\n\n        -- Stats fetch helper\n        local function getHomeStats()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return {} end\n            local stats = {}\n            local levelFolder = userData:FindFirstChild(\"Level\")\n            stats.Level = levelFolder and levelFolder:FindFirstChild(\"Level\") and tostring(levelFolder.Level.Value) or \"N/A\"\n            stats.Cash = userData:FindFirstChild(\"Cash\") and tostring(userData.Cash.Value) or \"N/A\"\n            stats.Rod = userData:FindFirstChild(\"FishingRod\") and tostring(userData.FishingRod.Value) or \"N/A\"\n            stats.Crystal = userData:FindFirstChild(\"Crystal\") and tostring(userData.Crystal.Value) or \"N/A\"\n            stats.EssenceOrb = userData:FindFirstChild(\"EssenceOrb\") and tostring(userData.EssenceOrb.Value) or \"N/A\"\n            stats.Bait = userData:FindFirstChild(\"EquippedBait\") and tostring(userData.EquippedBait.Value) or \"N/A\"\n            stats.FishCaught = userData:FindFirstChild(\"FishCaught\") and tostring(userData.FishCaught.Value) or \"N/A\"\n            stats.Ticket = userData:FindFirstChild(\"Ticket\") and tostring(userData.Ticket.Value) or \"N/A\"\n            stats.TraitReroll = userData:FindFirstChild(\"Trait Reroll\") and tostring(userData[\"Trait Reroll\"].Value) or \"N/A\"\n            stats.HeaviestWeight = userData:FindFirstChild(\"HeaviestWeight\") and tostring(userData.HeaviestWeight.Value) or \"N/A\"\n            stats.BaseHP = userData:FindFirstChild(\"BaseHP\") and tostring(userData.BaseHP.Value) or \"N/A\"\n            return stats\n        end, cframe = CFrame.new(-297, 9, 12), power = 0},\n        {name = \"Island 2\", cframe = CFrame.new(-1274, 21, -270), power = 17},\n        {name = \"Island 3\", cframe = CFrame.new(57, 9, 1115), power = 28},\n        {name = \"Island 4\", cframe = CFrame.new(-1343, 9, 1083), power = 35},\n        {name = \"Island 5\", cframe = CFrame.new(-12, 9, -1696), power = 45},\n        {name = \"Island 6\", cframe = CFrame.new(-1184, 20, -1652), power = 55},\n        {name = \"Island 7\", cframe = CFrame.new(1470, 9, -1685), power = 62},\n        {name = \"Island 8\", cframe = CFrame.new(1130, 9, 1364), power = 72},\n        {name = \"Island 9\", cframe = CFrame.new(1459, 8, -248), power = 90},\n        {name = \"Island 10\", cframe = CFrame.new(3028, 16, -124), power = 100},\n        -- Island 11 (if u have ego and tiger): chi duoc recommend khi co ca rod Ego va Tiger\n        {name = \"Island 11\", cframe = CFrame.new(-2498.64966, 9.27561855, -215.078888, 0.444082469, 1.84874409e-08, -0.895985901, -3.89493522e-08, 1, 1.32894518e-09, 0.895985901, 3.43079094e-08, 0.444082469), power = 110},\n        {name = \"Island 12\", cframe = CFrame.new(-2912.0498, 6.76233578, 1200.33838, 0.272515684, -2.71757763e-08, 0.962151349, -1.71733454e-08, 1, 3.31089112e-08, -0.962151349, -2.55460559e-08, 0.272515684), power = 120},\n        {name = \"Island 13\", cframe = CFrame.new(-2690.31543, 6.76233625, -1313.08179, -0.539970279, 1.03704998e-07, 0.841684103, 7.36837009e-08, 1, -7.59405978e-08, -0.841684103, 2.10127347e-08, -0.539970279), power = 130},\n    },\n    Reroll = { method = \"Instant\", teleported = false, oldPosition = nil, running = false, thread = nil },\n    buyRod = { method = \"Instant\", teleported = false, oldPosition = nil },\n    learnSkill = { method = \"Instant\", teleported = false, oldPosition = nil },\n    upgradeSkill = { method = \"Instant\", teleported = false, oldPosition = nil },\n    exchange = { method = \"Instant\", teleported = false, oldPosition = nil },\n    upgradeCharacter = { method = \"Instant\", teleported = false, oldPosition = nil },\n    favorites = { selectedFish = {}, autoEnabled = false, thread = nil },\n    AutoFarm = {\n        enabled = false,\n        selectedIsland = nil,\n        filter1 = nil,\n        filter2 = nil,\n        targetFishName = \"\",\n        teleported = false,\n        thread = nil,\n    },\n    LastMaoshan = false,\n    LastTaoist = false,\n    LastSpirit = false,\n    LastWeather = nil,\n    reportedJobId = game.JobId,\n    autoRecommendRunning = false,\n    autoRecommendThread = nil,\n    autoRebirthRunning = false,\n    autoRebirthThread = nil,\n    autoCraftRunning = false,\n    autoCraftThread = nil,\n    autoGachaRunning = false,\n    autoGachaThread = nil,\n    autoDoRunning = false,\n    autoDoThread = nil,\n    autoClaimRunning = false,\n    autoClaimThread = nil,\n    ticketTargetCount = 0,\n    ticketCurrentCount = 0,\n    ticketQuestActive = false,\n    ticketQuestClaimed = false,\n    savedRoutineFlags = nil,\n    craftBaitQuantity = 1,\n    craftBaitName = \"Rainbow Bait\",\n    selectedBait = nil,\n    buyBaitQuantity = 10,\n    buyBaitThreshold = 5,\n    selectedOptions = {\"Cash\", \"Level\"},\n    UpgradeCharacter = nil,\n    flying = false,\n    flySpeed = 50,\n    bg = nil,\n    bv = nil,\n    flyInputConnection = nil,\n    flyInputEndConnection = nil,\n    flyKeys = { Up = false, Down = false },\n    waterY = nil,\n    waterPart = nil,\n    waterPartsList = {},\n    waterWalkConnection = nil,\n    waterWalkEnabled = false,\n    BossKeywords = { \"boss\", \"raid\", \"giant\", \"king\", \"lord\" },\n    SecretBossKeywords = { \"secret\", \"hidden\", \"mythic\", \"event\", \"rare\" },\n    BossNameSet = {},\n    SecretBossNameSet = {},\n    autoCraftRodRunning = false,\n    autoCraftRodThread = nil,\n    enzoHitIndex = 0,\n    enzoPhaseActive = false,\n    enzoNextClick = 0,\n    fullBrightApplied = false,\n    enzoPrevP = nil,\n    enzoDir = 0,\n    enzoArmed = true,\n    autoGachaToggleRef = nil,\n    sellMethod1 = \"Spam\",\n    sellMethod2 = \"Instant\",\n    lastPosition = nil,\n    sellCooldown = 0,\n    craftRodMethod = \"Instant\",\n    lastCraftPosition = nil,\n    craftBaitMethod = \"Instant\",\n    buyBaitMethod = \"Instant\",\n    lastCraftBaitPosition = nil,\n    lastBuyBaitPosition = nil,\n    spectateToggle = false,\n    notificationsEnabled = true,\n    fakeNameEnabled = false,\n    fakeName = \"NexusPlayer\",\n    fakeDisplayName = \"NexusPlayer\",\n    fakeUserId = \"0\",\n    fakeIdMode = 1,\n    -- Guild display (neu game hien ten guild canh ten player -> doi ten guild\n    -- de khong bi report/ban). realGuildName=\"\" thi bo qua.\n    realGuildName = \"\",\n    fakeGuildName = \"NexusGuild\",\n    antiReportEnabled = true,\n    currentLanguage = \"auto\",\n    skillSeqIndex = 1,\n    lastSkillCastTime = 0,\n    SmartWeather = {\n        enabled = false,\n        selectedIslands = {\n            [\"Island 2\"] = true,\n            [\"Island 3\"] = true,\n            [\"Island 5\"] = true,\n            [\"Island 6\"] = true,\n            [\"Island 7\"] = true,\n            [\"Island 8\"] = true,\n        },\n        activeOverride = false,\n        savedCFrame = nil,\n        savedFlags = nil,\n        targetIsland = nil,\n    },\n    questFarmingIsland = \"Auto (Recommend)\",\n    isDoingUseBaitQuest = false,\n}\ndo\n    -- Override NexusLib.Notify de kiem tra toggle va ho tro ca method (:) lan direct (.)\n    if NexusLib and NexusLib.Notify then\n        local originalNotify = NexusLib.Notify\n        NexusLib.Notify = function(selfOrConfig, maybeConfig)\n            if NexusState and NexusState.notificationsEnabled == false then\n                return\n            end\n            local config = maybeConfig\n            if not config and type(selfOrConfig) == \"table\" then\n                if selfOrConfig.Title or selfOrConfig.Message or selfOrConfig.Duration then\n                    config = selfOrConfig\n                end\n            end\n            config = config or {}\n\n            pcall(function()\n                originalNotify(NexusLib, config)\n            end)\n        end\n    end\nend\n\n-- ============================================================\n-- ===== NEXUS USERS PROTECTION (ANTI-REPORT) =====\n-- ============================================================\ndo\n    pcall(function()\n        LocalPlayer:SetAttribute(\"NexusUser\", true)\n        if LocalPlayer.Character then\n            LocalPlayer.Character:SetAttribute(\"NexusUser\", true)\n        end\n        LocalPlayer.CharacterAdded:Connect(function(char)\n            pcall(function()\n                LocalPlayer:SetAttribute(\"NexusUser\", true)\n                char:SetAttribute(\"NexusUser\", true)\n            end)\n        end)\n    end)\n\n    pcall(function()\n        if hookmetamethod and not _G.NexusNamecallHooked then\n            _G.NexusNamecallHooked = true\n            local oldNamecall\n            oldNamecall = hookmetamethod(game, \"__namecall\", function(self, ...)\n                local method = getnamecallmethod()\n                if (method == \"ReportAbuse\" or method == \"reportAbuse\") and self == Players then\n                    local args = {...}\n                    local target = args[1]\n                    local isNexusUser = false\n                    if typeof and typeof(target) == \"Instance\" then\n                        if typeof(target) == \"Instance\" and typeof(target) == \"Instance\" and target:IsA(\"Player\") then\n                            if target:GetAttribute(\"NexusUser\") or (target.Character and target.Character:GetAttribute(\"NexusUser\")) then\n                                isNexusUser = true\n                            end\n                        end\n                    elseif type(target) == \"string\" then\n                        local p = Players:FindFirstChild(target)\n                        if p and (p:GetAttribute(\"NexusUser\") or (p.Character and p.Character:GetAttribute(\"NexusUser\"))) then\n                            isNexusUser = true\n                        end\n                    end\n                    if isNexusUser and NexusState.antiReportEnabled ~= false then\n                        NexusLib:Notify({\n                            Title = \"Nexus Shield\",\n                            Message = \"You cannot report another Nexus Hub user!\",\n                            Duration = 3\n                        })\n                        return nil\n                    end\n                end\n                return oldNamecall(self, ...)\n            end)\n        end\n    end)\nend\n\n-- ============================================================\n-- ===== AUTO LANGUAGE (I18N) =====\n-- ============================================================\nlocal I18n = {}\ndo\n    local LocalizationService = Services.LocalizationService or game:GetService(\"LocalizationService\")\n    local rawLocale = \"en\"\n    pcall(function()\n        rawLocale = string.lower(\n    