"Pumili ng player",\n            ["Select Quest Type"] = "Pumili ng uri ng quest",\n            ["Select Skill"] = "Pumili ng skill",\n            ["Target Trait"] = "Target na trait",\n            ["Choose a Bait"] = "Pumili ng pain",\n            ["Choose an island"] = "Pumili ng isla",\n            ["Choose an item"] = "Pumili ng item",\n            ["Buy Amount"] = "Dami ng bibilhin",\n            ["Buy When Below"] = "Bumili kapag mas mababa",\n            ["Number of baits to craft"] = "Bilang ng pain na gagawin",\n            ["Quantity"] = "Dami",\n            ["Tickets per roll"] = "Ticket kada roll",\n            ["Fly Speed"] = "Bilis ng lipad",\n            ["Walk Speed"] = "Bilis ng lakad",\n            ["Risk hits/sec (1-200)"] = "Pindot/seg (1-200)",\n            ["Safe band (0.01-0.17)"] = "Ligtas na banda (0.01-0.17)",\n            ["Fake Username"] = "Pekeng username",\n            ["Fake Display Name"] = "Pekeng display name",\n            ["Name Of The Fish (Optional)"] = "Pangalan ng isda (opsyonal)",\n            ["Select bait for material farming"] = "Pumili ng pain para sa material farming",\n            ["Choose A Skill That Needs To Upgrade"] = "Pumili ng skill na i-upgrade",\n            ["Learn Skill NPC"] = "NPC para matuto ng skill",\n            ["Secret Rods"] = "Mga secret rod",\n            ["Misc NPCs"] = "Ibang NPC",\n            ["Players"] = "Mga player",\n            ["Allowed Weather Islands"] = "Mga pinapayagang isla ayon sa panahon",\n            ["Skills to press"] = "Skill na pipindutin",\n            ["Select fish to auto-favourite"] = "Pumili ng isda para sa auto-favourite",\n            ["Select Skills to Learn"] = "Pumili ng skill na matutunan",\n            ["Select 2 upgrade options"] = "Pumili ng 2 upgrade option",\n            ["Language"] = "Wika",\n            ["Language set to: "] = "Wika ay itinakda sa: ",\n        },\n    }\n\n    function I18n.getCurrentLanguage()\n        if NexusState.currentLanguage == "auto" then\n            return NexusState.detectedLanguage or "en"\n        end\n        return NexusState.currentLanguage or "en"\n    end\n\n    function I18n.get(key, fallback)\n        if not key or type(key) ~= "string" then return fallback or key end\n        local lang = I18n.getCurrentLanguage()\n        if lang == "en" then return fallback or key end\n        local dict = DICTIONARY[lang]\n        if dict and dict[key] then return dict[key] end\n        return fallback or key\n    end\n\n    local function translateObject(obj)\n        if not obj or typeof(obj) ~= "Instance" then return end\n        local lang = I18n.getCurrentLanguage()\n        if lang == "en" then return end\n        pcall(function()\n            if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then\n                local currentText = obj.Text\n                if not currentText or #currentText == 0 then return end\n                \n                local dict = DICTIONARY[lang]\n                \n                local orig = obj:GetAttribute("NexusOrigText")\n                if not orig or (dict and dict[currentText]) then\n                    orig = currentText\n                    obj:SetAttribute("NexusOrigText", orig)\n                end\n                \n                if orig and #orig > 0 then\n                    if lang == "en" then\n                        if obj.Text ~= orig then\n                            obj.Text = orig\n                        end\n                    else\n                        local trans = dict and dict[orig]\n                        if trans and obj.Text ~= trans then\n                            obj.Text = trans\n                        end\n                    end\n                end\n            end\n        end)\n    end\n\n    local function applyLanguageToGui(gui)\n        if not gui then return end\n        pcall(function()\n            for _, desc in ipairs(gui:GetDescendants()) do\n                translateObject(desc)\n            end\n        end)\n    end\n\n    function I18n.applyLanguage()\n        task.wait(2)\n                end\n            elseif qType == "BossQuest" then\n                local island = getRecommendedIsland()\n                if not island then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "No suitable island found!", Duration = 2 })\n                    return\n                end\n                if not teleportToIsland(island) then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Teleport failed!", Duration = 2 })\n                    return\n                end\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = true\n                Fishing.Flags.AutoFarmSecretBoss = false\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Boss daily started on " .. island.name, Duration = 2 })\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild("Progression")\n                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then\n                        if newProgress.Value >= 10 then\n                            NexusLib:Notify({ Title = "Daily Quest", Message = "Boss daily completed!", Duration = 3 })\n                            break\n                        end\n                    end\n                    task.wait(2)\n                end\n            elseif qType == "Bait" then\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Bait daily: buying Basic Bait...", Duration = 2 })\n                local buyEvent = Events:FindFirstChild("BuyBait")\n                if not buyEvent then\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "BuyBait remote not found!", Duration = 2 })\n                    return\n                end\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild("Progression")\n                    if typeof(newProgress) == "Instance" and newProgress:IsA("NumberValue") then\n                        if newProgress.Value >= 25 then\n                            NexusLib:Notify({ Title = "Daily Quest", Message = "Bait daily completed!", Duration = 3 })\n                            break\n                        end\n                    end\n                    pcall(function() buyEvent:FireServer("Basic Bait", 1) end)\n                    task.wait(0.5)\n                end\n            else\n                NexusLib:Notify({ Title = "Daily Quest", Message = "Unknown quest type: " .. qType, Duration = 2 })\n            end\n            restoreRoutineFlags()\n        end\n\n        -- Toggle Auto Do Daily Quest\n        local autoDailyToggle = Cfg.register(DailySection:CreateToggle(Cfg.wrap("Toggle", "Auto Do Daily Quest", {\n            Name = "Auto Do Daily Quest",\n            Default = false,\n            Callback = function(value)\n                dailyRunning = value\n                if value then\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    dailyThread = task.spawn(function()\n                        while dailyRunning do\n                            pcall(doDailyQuest)\n                            if dailyRunning then\n                                task.wait(5)\n                            end\n                        end\n                    end)\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily started!", Duration = 2 })\n                else\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    restoreRoutineFlags()\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Do Daily Quest", {\n            Name = "Auto Do Daily Quest",\n            Default = false,\n            Callback = function(value)\n                dailyRunning = value\n                if value then\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    dailyThread = task.spawn(function()\n                        while dailyRunning do\n                            pcall(doDailyQuest)\n                            if dailyRunning then\n                                task.wait(5)\n                            end\n                        end\n                    end)\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily started!", Duration = 2 })\n                else\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    restoreRoutineFlags()\n                    NexusLib:Notify({ Title = "Daily Quest", Message = "Auto Daily stopped", Duration = 2 })\n                end\n            end\n        })\n\n        -- ===== CLAIM DAILY REWARDS BUTTON =====\n        DailySection:CreateButton({\n            Name = "Claim Daily Rewards",\n            Callback = function()\n                local dailyRewardEvent = Events:FindFirstChild("DailyReward")\n                if not dailyRewardEvent then\n                    NexusLib:Notify({ Title = "Daily Rewards", Message = "DailyReward remote not found!", Duration = 3 })\n                    return\n                end\n                NexusLib:Notify({ Title = "Daily Rewards", Message = "Claiming all 7 daily rewards...", Duration = 2 })\n                task.spawn(function()\n                    for i = 1, 7 do\n                        pcall(function()\n                            dailyRewardEvent:FireServer(i)\n                        end)\n                        task.wait(0.5)\n                    end\n                    NexusLib:Notify({ Title = "Daily Rewards", Message = "All 7 daily rewards claimed!", Duration = 3 })\n                end)\n            end\n        })\n    end\n\n    -- ===== MATERIAL FARMING =====\n    do\n        local MaterialSection = QuestsTab:CreateSection("Material Farming")\n        local MatFishingAreaRarity\n        pcall(function()\n            MatFishingAreaRarity = require(Info.FishingAreaRarity)\n        end)\n        if not MatFishingAreaRarity then\n            MatFishingAreaRarity = {\n                ["Beginning Isle"] = {}, ["Bamboo Isle"] = {}, ["Fallout Isle"] = {},\n                ["Sovereign Isle"] = {}, ["Perch Isle"] = {}, ["Frost Isle"] = {},\n                ["Coconut Isle"] = {}, ["Amber Isle"] = {}, ["Battlefield Isle"] = {},\n                ["Mistpeak Isle"] = {}, ["Exclusive"] = {}, ["Secret Boss"] = {},\n            }\n        end\n\n        local matIslandDisplayNames = {\n            ["Beginning Isle"] = "Island 1", ["Bamboo Isle"] = "Island 2", ["Fallout Isle"] = "Island 3",\n            ["Sovereign Isle"] = "Island 4", ["Perch Isle"] = "Island 5", ["Frost Isle"] = "Island 6",\n            ["Coconut Isle"] = "Island 7", ["Amber Isle"] = "Island 8", ["Battlefield Isle"] = "Island 9",\n            ["Mistpeak Isle"] = "Island 10", ["Exclusive"] = "Exclusive", ["Secret Boss"] = "Secret Boss"\n        }\n        local matIslandOrder = {\n            "Beginning Isle","Bamboo Isle","Fallout Isle","Sovereign Isle","Perch Isle","Frost Isle",\n            "Coconut Isle","Amber Isle","Battlefield Isle","Mistpeak Isle","Exclusive","Secret Boss"\n        }\n        local matIslandNameToIsland = {}\n        for _, island in ipairs(NexusState.islands) do matIslandNameToIsland[island.name] = island end\n        for rarityName, displayName in pairs(matIslandDisplayNames) do\n            for _, island in ipairs(NexusState.islands) do\n                if island.name == displayName then matIslandNameToIsland[rarityName] = island end\n            end\n        end\n\n        local function matGetIslandsForFish(fishName)\n            local result = {}\n            for _, islandName in ipairs(matIslandOrder) do\n                local fishList = MatFishingAreaRarity[islandName]\n                if fishList and fishList[fishName] then table.insert(result, islandName) end\n            end\n            return result\n        end\n\n        local function matGetMaterialCount(fishName, minKg, maxKg)\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return 0 end\n            local inventory = userData:FindFirstChild("Inventory")\n            if not inventory then return 0 end\n            local count = 0\n            for _, item in pairs(inventory:GetChildren()) do\n                if item.Name == fishName then\n                    local weightString = nil\n                    if typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("StringValue") then\n                        local parts = {}\n                        for part in string.gmatch(item.Value, "[^|]+") do table.insert(parts, part) end\n                        if #parts >= 2 then weightString = parts[2]:gsub("^%s+", ""):gsub("%s+$", "") end\n                    elseif typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("NumberValue") or item:IsA("IntValue") then\n                        weightString = tostring(item.Value)\n                    end\n                    if weightString then\n                        local weight = tonumber(weightString)\n                        if weight and weight >= minKg and weight <= maxKg then\n                            count = count + 1\n                        end\n                    end\n                end\n            end\n            return count\n        end\n\n        local function matTeleportToIsland(islandName)\n            local island = matIslandNameToIsland[islandName]\n            if not island then return false end\n            local char = LocalPlayer.Character\n            if not char then return false end\n            local hrp = char:FindFirstChild("HumanoidRootPart")\n            if hrp then\n                hrp.AssemblyLinearVelocity = Vector3.zero\n                hrp.AssemblyAngularVelocity = Vector3.zero\n                hrp.CFrame = CFrame.new(island.cframe.Position) + Vector3.new(0, 5, 0)\n                return true\n            end\n            return false\n        end\n\n        local function matGetWeather()\n            local mg = LocalPlayer:FindFirstChild("PlayerGui") and LocalPlayer.PlayerGui:FindFirstChild("MainGui")\n            if mg then\n                local info = mg:FindFirstChild("Info")\n                local infoFrame = info and info:FindFirstChild("Info")\n                local weatherFrame = infoFrame and infoFrame:FindFirstChild("Weather")\n                local val = weatherFrame and weatherFrame:FindFirstChild("Value")\n                if val and typeof(val) == "Instance" then\n                    local text = ((typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value))\n                    return (text:gsub("Weather:%s*", ""))\n                end\n            end\n            return "Clear"\n        end\n\n        local function matCancelFishing()\n            local char = LocalPlayer.Character\n            if not char then return end\n            if not char:GetAttribute("Fishing") then return end\n            local root = char:FindFirstChild("HumanoidRootPart")\n            if root then pcall(function() Events.Fishing:FireServer(root.CFrame) end) end\n            if Fishing.BossFarm.CurrentToken then\n                pcall(function() Events.FishingMinigame:FireServer(false, Fishing.BossFarm.CurrentToken) end)\n            end\n        end\n\n        local function matEnableFishing()\n            if not NexusState.materialFarmingSavedFlags then\n                Nexsk.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = "Gacha", Message = "Stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Gacha", {\n            Name = "Auto Gacha",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGachaRunning = value\n                if value then\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusState.autoGachaThread = task.spawn(function()\n                        while NexusState.autoGachaRunning do\n                            pcall(function()\n                                local ticketCount = GetTicketCount()\n                                local needed = tonumber(selectedAmount) or 1\n                                local crystalCount = GetCrystals()\n                                local canRoll = false\n                                if ticketCount >= needed then\n                                    canRoll = true\n                                else\n                                    local missing = needed - ticketCount\n                                    local crystalsNeeded = missing * 5\n                                    if crystalCount >= crystalsNeeded then\n                                        canRoll = true\n                                    else\n                                        NexusLib:Notify({\n                                            Title = "Gacha",\n                                            Message = "Not enough tickets/crystals! Need " .. crystalsNeeded .. " crystals (have " .. crystalCount .. "). Stopping.",\n                                            Duration = 4\n                                        })\n                                        NexusState.autoGachaRunning = false\n                                        return\n                                    end\n                                end\n                                if canRoll then\n                                    local isTen = (selectedAmount == "10")\n                                    Events.Gacha:FireServer(isTen, selectedBanner)\n                                    NexusLib:Notify({\n                                        Title = "Gacha",\n                                        Message = "Rolled " .. selectedAmount .. " ticket(s) on " .. selectedBanner,\n                                        Duration = 2\n                                    })\n                                end\n                            end)\n                            task.wait(2)\n                        end\n                    end)\n                else\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = "Gacha", Message = "Stopped", Duration = 2 })\n                end\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== EXCHANGE TAB =====\n-- ============================================================\ndo\n    local ExchangeTab = Window:CreateTab("Exchange")\n    local ExchangeSection = ExchangeTab:CreateSection("Exchange Items")\n\n    local exchangeAmount = 1\n    local exchangeType = "Trait Reroll"\n\n    Cfg.register(ExchangeSection:CreateTextbox(Cfg.wrap("Textbox", "Quantity", {\n        Name = "Quantity",\n        Placeholder = "1",\n        Default = "1",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })), "Textbox", "Quantity", {\n        Name = "Quantity",\n        Placeholder = "1",\n        Default = "1",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })\n\n    Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose an item", {\n        Name = "Choose an item",\n        Options = {"Trait Reroll", "EssenceOrb"},\n        Default = "Trait Reroll",\n        Callback = function(value) exchangeType = value end\n    })), "Dropdown", "Choose an item", {\n        Name = "Choose an item",\n        Options = {"Trait Reroll", "EssenceOrb"},\n        Default = "Trait Reroll",\n        Callback = function(value) exchangeType = value end\n    })\n\n    local exchangeMethodDropdown = Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap("Dropdown", "Exchange Method", {\n        Name = "Exchange Method",\n        Options = {"Instant", "Teleport"},\n        Default = NexusState.exchange.method or "Instant",\n        Callback = function(value) NexusState.exchange.method = value end\n    })), "Dropdown", "Exchange Method", {\n        Name = "Exchange Method",\n        Options = {"Instant", "Teleport"},\n        Default = NexusState.exchange.method or "Instant",\n        Callback = function(value) NexusState.exchange.method = value end\n    })\n\n    ExchangeSection:CreateButton({\n        Name = "Exchange now",\n        Callback = function()\n            local userId = LocalPlayer.UserId\n            local userData = Data:FindFirstChild(tostring(userId))\n            if not userData then\n                NexusLib:Notify({ Title = "Exchange", Message = "Player data not found!", Duration = 2 })\n                return\n            end\n            local crystal = userData:FindFirstChild("Crystal")\n            local cash = userData:FindFirstChild("Cash")\n            if not crystal or not cash then\n                NexusLib:Notify({ Title = "Exchange", Message = "Crystal or Cash not found!", Duration = 2 })\n                return\n            end\n            local qty = exchangeAmount\n            local crystalNeed = qty * 5\n            local cashNeed = qty * 5000000\n            if crystal.Value < crystalNeed then\n                NexusLib:Notify({ Title = "Exchange", Message = "Not enough Crystals! Need " .. crystalNeed .. ", have " .. crystal.Value, Duration = 3 })\n                return\n            end\n            if cash.Value < cashNeed then\n                NexusLib:Notify({ Title = "Exchange", Message = "Not enough Cash! Need " .. cashNeed .. ", have " .. cash.Value, Duration = 3 })\n                return\n            end\n\n            NexusState.exchange.teleported = false\n            NexusState.exchange.oldPosition = nil\n            if NexusState.exchange.method == "Teleport" then\n                local npc = Workspace:FindFirstChild("NPC")\n                if npc then\n                    local func = npc:FindFirstChild("Function")\n                    if func then\n                        local nanjiang = func:FindFirstChild("Nanjiang")\n                        if typeof(nanjiang) == "Instance" and nanjiang:IsA("Model") then\n                            local hrp = nanjiang:FindFirstChild("HumanoidRootPart")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild("HumanoidRootPart")\n                                    if root then\n                                        NexusState.exchange.oldPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        NexusState.exchange.teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                if not NexusState.exchange.teleported then\n                    NexusLib:Notify({ Title = "Exchange", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })\n                end\n            end\n\n            local success, err = pcall(function()\n                Events.Exchange:FireServer(exchangeType, qty)\n            end)\n\n            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then\n                task.wait(0.2)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild("HumanoidRootPart")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)\n                        NexusState.exchange.oldPosition = nil\n                        NexusState.exchange.teleported = false\n                    end\n                end\n            end\n\n            if success then\n                NexusLib:Notify({ Title = "Exchange", Message = "Exchanged " .. qty .. " " .. exchangeType .. "!", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Exchange", Message = "Exchange failed: " .. tostring(err), Duration = 2 })\n            end\n        end\n    })\nend\n\n-- ============================================================\n-- ===== QUESTS TAB =====\n-- ============================================================\ndo\n    local QuestsTab = Window:CreateTab("Quests")\n\n    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.\n    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.\n    NexusState.ticketLastFire = NexusState.ticketLastFire or 0\n    NexusState.ticketFailCount = NexusState.ticketFailCount or 0\n    local function ticketGoFire(action)\n        if _G and _G.Events then\n            local sd = _G.Events:FindFirstChild("StartDialogue")\n            local cd = _G.Events:FindFirstChild("ChooseDialogueOption")\n            if not sd or not cd then return false end\n        end\n        local giver = nil\n        pcall(function()\n            local npc = Workspace:FindFirstChild("NPC")\n            local npcFunc = npc and npc:FindFirstChild("Function")\n            giver = npcFunc and npcFunc:FindFirstChild("Ticket Quest Giver")\n        end)\n        if not giver then return false end\n        local extraData = { giver }\n        local charNow = LocalPlayer.Character\n        local root = charNow and charNow:FindFirstChild("HumanoidRootPart")\n        local giverPos = nil\n        pcall(function()\n            if typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("Model") then\n                local hrp = giver:FindFirstChild("HumanoidRootPart")\n                if hrp then\n                    giverPos = hrp.Position\n                elseif giver.PrimaryPart then\n                    giverPos = giver.PrimaryPart.Position\n                else\n                    giverPos = giver:GetPivot().Position\n                end\n            elseif typeof(giver) == "Instance" and typeof(giver) == "Instance" and giver:IsA("BasePart") then\n                giverPos = giver.Position\n            end\n        end)\n        local origCF = root and root.CFrame\n        if root and giverPos then\n            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)\n            task.wait(0.45)\n        end\n        pcall(function()\n            Events.StartDialogue:FireServer("Ticket Quest Giver", giver)\n        end)\n        task.wait(0.25)\n        pcall(function()\n            Events.ChooseDialogueOption:FireServer("Ticket Quest Giver",             end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "NPC Teleport", Message = "NPC not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "NPC Teleport", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "NPC Teleport", Message = "Teleported to " .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = "Sage Yijiu"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap("Dropdown", "Learn Skill NPC", {\n            Name = "Learn Skill NPC",\n            Options = {"Sage Yijiu"},\n            Default = "Sage Yijiu",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), "Dropdown", "Learn Skill NPC", {\n            Name = "Learn Skill NPC",\n            Options = {"Sage Yijiu"},\n            Default = "Sage Yijiu",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = "Teleport to selected NPC",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild("NPC") \n                    and workspace.NPC:FindFirstChild("LearnSkill") \n                    and workspace.NPC.LearnSkill:FindFirstChild("Sage Yijiu")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "Learn Skill", Message = "Sage Yijiu not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "Learn Skill", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "Learn Skill", Message = "Teleported to Sage Yijiu", Duration = 2 })\n            end\n        })\n        -- ===== SECRET RODS SECTION =====\n        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)\n        local function getSecretRodList()\n            local rods = {}\n            local secretRodFolder = workspace:FindFirstChild("SecretRod")\n            if not secretRodFolder then return rods end\n            \n            for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                    table.insert(rods, child.Name)\n                end\n            end\n            return rods\n        end\n        \n        local rodList = getSecretRodList()\n        if #rodList == 0 then\n            table.insert(rodList, "No Secret Rods found")\n        end\n        \n        local selectedRod = rodList[1]\n        \n        -- Dropdown\n        local rodDropdown = NpcSection:CreateDropdown({\n            Name = "Secret Rods",\n            Options = rodList,\n            Default = selectedRod,\n            Callback = function(value)\n                selectedRod = value\n            end\n        })\n        \n        -- Teleport button\n        NpcSection:CreateButton({\n            Name = "Teleport to selected Secret Rod",\n            Callback = function()\n                if not selectedRod or selectedRod == "No Secret Rods found" then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "No Secret Rod selected!", Duration = 2 })\n                    return\n                end\n                \n                local secretRodFolder = workspace:FindFirstChild("SecretRod")\n                if not secretRodFolder then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "SecretRod folder not found!", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "Secret Rod not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "Secret Rod", Message = "Teleported to " .. selectedRod, Duration = 2 })\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== SETTINGS TAB =====\n-- ============================================================\ndo\n    local SettingsTab = Window:CreateTab("Settings")\n\n    -- ===== CONFIG SECTION (save / load / auto-load / import-export) =====\n    do\n        local CfgUI = SettingsTab:CreateSection("Config")\n        local Cfg = runtimeEnv.NexusConfig\n\n        CfgUI:CreateButton({\n            Name = "Save Config",\n            Callback = function() Cfg.save() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Load Config",\n            Callback = function() Cfg.load() end,\n        })\n\n        CfgUI:CreateToggle({\n            Name = "Auto Load Config",\n            Default = false,\n            Callback = function(value)\n                if not (writefile and isfile) then\n                    NexusLib:Notify({ Title = "Config", Message = "This executor cannot save files.", Duration = 3 })\n                    return\n                end\n                if value then\n                    Cfg.save(Cfg.AUTO_FILE)\n                else\n                    pcall(function()\n                        if isfile(Cfg.AUTO_FILE) and delfile then delfile(Cfg.AUTO_FILE) end\n                    end)\n                end\n            end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Export Config (Copy Code)",\n            Callback = function() Cfg.exportCode() end,\n        })\n\n        local importBox = CfgUI:CreateTextbox({\n            Name = "Import Config Code",\n            Placeholder = "Paste code, then press Import",\n            Default = "",\n            Callback = function() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Import Config",\n            Callback = function()\n                local code = ""\n                pcall(function() code = importBox.Get() end)\n                Cfg.importCode(code)\n            end,\n        })\n    end\n    local CharSection = SettingsTab:CreateSection("Character")\n\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap("Textbox", "Walk Speed", { Name = "Walk Speed", Placeholder = "16", Default = "16", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })), "Textbox", "Walk Speed", { Name = "Walk Speed", Placeholder = "16", Default = "16", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })\n\n    local function startFly()\n        local c = LocalPlayer.Character\n        if not c or not c:FindFirstChild("HumanoidRootPart") then return end\n        if NexusState.flying then return end\n        if NexusState.bg then NexusState.bg:Destroy() end\n        if NexusState.bv then NexusState.bv:Destroy() end\n        local h = c.HumanoidRootPart\n        NexusState.bg = Instance.new("BodyGyro", h)\n        NexusState.bg.P = 9e4\n        NexusState.bg.maxTorque = Vector3.new(9e9,9e9,9e9)\n        NexusState.bg.cframe = h.CFrame\n        NexusState.bv = Instance.new("BodyVelocity", h)\n        NexusState.bv.velocity = Vector3.new(0,0,0)\n        NexusState.bv.maxForce = Vector3.new(9e9,9e9,9e9)\n        NexusState.flying = true\n        local humanoid = c:FindFirstChildOfClass("Humanoid")\n        if humanoid then humanoid.PlatformStand = true end\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect() end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect() end\n        NexusState.flyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)\n            if gameProcessed then return end\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = true end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = true end\n        end)\n        NexusState.flyInputEndConnection = UserInputService.InputEnded:Connect(function(input)\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = false end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = false end\n        end)\n    end\n\n    local function stopFly()\n        NexusState.flying = false\n        NexusState.flyKeys.Up, NexusState.flyKeys.Down = false, false\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect(); NexusState.flyInputConnection = nil end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect(); NexusState.flyInputEndConnection = nil end\n        if NexusState.bg then NexusState.bg:Destroy(); NexusState.bg = nil end\n        if NexusState.bv then NexusState.bv:Destroy(); NexusState.bv = nil end\n        local c = LocalPlayer.Character\n        if c then\