'     local found\n        for _, fname in ipairs(GUARD.KEY_FILES) do\n            pcall(function()\n                if not found and isfile and readfile and isfile(fname) then\n                    local s = readfile(fname)\n                    if type(s) == "string" and #trim(s) >= 4 then found = trim(s) end\n                end\n            end)\n            if found then break end\n        end\n        return found\n    end\n\n    local function notify(msg)\n        -- 1) print luon hoat dong tren moi executor\n        pcall(function() print("[Nexus Hub] " .. tostring(msg)) end)\n        -- 2) NexusLib neu co (khong dung notify Roblox)\n        pcall(function()\n            local slib = _rt.NexusLib\n            if slib and slib.Notify then slib:Notify({ Title = "Nexus Hub", Message = msg, Duration = 6 }) end\n        end)\n    end\n\n    local function deny(reason)\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport("Nexus: Thong bao key", tostring(reason) ..\n                    "\\n\\nExecute source truc tiep da bi KHOA. Phai dung loader hwfnew de vao.")\n            end\n        end)\n        LP:Kick("Nexus: " .. tostring(reason))\n    end\n\n    -- ================== B\xE1\xBA\xA2O V\xE1\xBB\x86 TOKEN HANDOFF CH\xE1\xBB\x90NG BYPASS ==================\n    -- Ch\xE1\xBB\x91ng tr\xC3\xB2 bypass g\xC3\xB5: getgenv().NexusPremiumVerified = true\n    -- B\xE1\xBA\xAFt bu\xE1\xBB\x99c ph\xE1\xBA\xA3i c\xC3\xB3 Server Nonce h\xE1\xBB\xA3p l\xE1\xBB\x87 t\xE1\xBB\xAB Loader v\xE1\xBB\xABa g\xE1\xBB\xADi sang v\xC3\xA0 ti\xC3\xAAu th\xE1\xBB\xA5 ngay (One-time token).\n    local serverNonce = _rt.NexusGuardNonce\n    _rt.NexusGuardNonce = nil -- Ti\xC3\xAAu th\xE1\xBB\xA5 ngay l\xE1\xBA\xADp t\xE1\xBB\xA9c token d\xC3\xB9ng 1 l\xE1\xBA\xA7n\n\n    local handoffTier = string.upper(tostring(_rt.NexusVerifiedTier or ""))\n    local isValidHandoff = false\n\n    if type(serverNonce) == "string" and #serverNonce >= 8 and handoffTier == "PREMIUM" then\n        isValidHandoff = true\n    elseif _rt.NexusPremiumVerified == true and type(_rt.Key) == "string" and #_rt.Key >= 6 and handoffTier == "PREMIUM" then\n        isValidHandoff = true\n    end\n\n    -- X\xC3\xB3a to\xC3\xA0n b\xE1\xBB\x99 c\xE1\xBB\x9D runtime \xC4\x91\xE1\xBB\x83 kh\xC3\xB4ng b\xE1\xBB\x8B t\xC3\xA1i s\xE1\xBB\xAD d\xE1\xBB\xA5ng\n    _rt.NexusPremiumVerified = nil\n    _rt.NexusFreemiumVerified = nil\n    _rt.NexusMainLoaded = nil\n    _rt.NexusVerifiedTier = nil\n\n    if not isValidHandoff then\n        -- Execute source tr\xE1\xBB\xB1c ti\xE1\xBA\xBFp ho\xE1\xBA\xB7c c\xE1\xBB\x91 t\xC3\xACnh set c\xE1\xBB\x9D gi\xE1\xBA\xA3 m\xE1\xBA\xA1o -> KICK ngay\n        local reason = "Bao mat: Khong the thuc thi Nexus Premium truc tiep. Phai qua loader chinh thuc!"\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport("Nexus Security", reason)\n            end\n        end)\n        LP:Kick("Nexus: " .. reason)\n        while true do task.wait(9999) end\n        return\n    end\n\n    _rt.NexusPremiumVerified = true\nend\n-- ===== END ANTI-BYPASS GUARD =====\n\nlocal runtimeEnv = (getgenv and getgenv()) or _G\n\n-- ===== NEXUSLIB LOADER =====\npcall(function() runtimeEnv.NexusStage("tai NexusLib") end)\nlocal NexusLib = runtimeEnv.NexusLib\nif not NexusLib then\n    local LIB_URL = "https://raw.githubusercontent.com/Ngmankhoi/my-hub/main/NexusLib.lua?v=20261011"\n    local source = nil\n    pcall(function()\n        if isfile and readfile and isfile("NexusLib.lua") then\n            local s = readfile("NexusLib.lua")\n            if type(s) == "string" and #s > 5000 and s:find("CreateWindow", 1, true) then source = s end\n        end\n    end)\n    if not source then\n        local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n        if type(reqFn) == "function" then\n            pcall(function()\n                local r = reqFn({ Url = LIB_URL, Method = "GET" })\n                local body = r and (r.Body or r.body)\n                if type(body) == "string" and #body > 5000 then source = body end\n            end)\n        end\n    end\n    if not source then\n        pcall(function() local s = game:HttpGet(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        pcall(function() local s = game:GetService("HttpService"):GetAsync(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        local msg = "[Nexus] Could not download NexusLib. This executor lacks HTTP support."\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    if type(loadstring) ~= "function" then\n        pcall(function() runtimeEnv.NexusReport("Nexus: executor not supported", "This executor has no loadstring -> the hub cannot run.\\nUse a different executor.") end)\n        return\n    end\n    local chunk, compileErr = loadstring(source, "@NexusLib.lua")\n    if not chunk then\n        local msg = "[Nexus] NexusLib compile error: " .. tostring(compileErr)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    local ok, lib = pcall(chunk)\n    if not ok or type(lib) ~= "table" then\n        local msg = "[Nexus] NexusLib runtime error: " .. tostring(lib)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    NexusLib = lib\n    runtimeEnv.NexusLib = lib\nend\n\nif runtimeEnv.MinigameAnchorLock then pcall(function() runtimeEnv.MinigameAnchorLock:Disconnect() end) end\nif runtimeEnv.NexusFrameConnection then runtimeEnv.NexusFrameConnection:Disconnect() runtimeEnv.NexusFrameConnection = nil end\nif runtimeEnv.NexusBossFightThread then task.cancel(runtimeEnv.NexusBossFightThread) runtimeEnv.NexusBossFightThread = nil end\nif runtimeEnv.NexusFightEnzoThread then task.cancel(runtimeEnv.NexusFightEnzoThread) runtimeEnv.NexusFightEnzoThread = nil end\nif runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) runtimeEnv.NexusRhyLoop = nil end\nif runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) runtimeEnv.AntiAFKConnection = nil end\nif runtimeEnv.NexusSpaceGuardConnection then pcall(function() runtimeEnv.NexusSpaceGuardConnection:Disconnect() end) runtimeEnv.NexusSpaceGuardConnection = nil end\nif runtimeEnv.NexusSelectableGuardConnection then pcall(function() runtimeEnv.NexusSelectableGuardConnection:Disconnect() end) runtimeEnv.NexusSelectableGuardConnection = nil end\nif runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) runtimeEnv.NexusNoclipConn = nil end\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) runtimeEnv.NexusMinigameConn = nil end\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) runtimeEnv.NexusSlamConn = nil end\n\n-- ===== SESSION EPOCH =====\nruntimeEnv.NexusEpoch = (runtimeEnv.NexusEpoch or 0) + 1\nlocal MY_EPOCH = runtimeEnv.NexusEpoch\nlocal function alive() return runtimeEnv.NexusEpoch == MY_EPOCH end\n\n-- ===== SERVICES =====\nlocal Services = {\n    Players = game:GetService("Players"),\n    ReplicatedStorage = game:GetService("ReplicatedStorage"),\n    RunService = game:GetService("RunService"),\n    VirtualUser = game:GetService("VirtualUser"),\n    UserInputService = game:GetService("UserInputService"),\n    Lighting = game:GetService("Lighting"),\n    TweenService = game:GetService("TweenService"),\n    Workspace = game:GetService("Workspace"),\n    Camera = game:GetService("Workspace").CurrentCamera,\n    HttpService = game:GetService("HttpService"),\n    GuiService = game:GetService("GuiService"),\n    TeleportService = game:GetService("TeleportService"),\n    RbxAnalyticsService = game:GetService("RbxAnalyticsService"),\n}\nlocal Players = Services.Players\nlocal ReplicatedStorage = Services.ReplicatedStorage\nlocal RunService = Services.RunService\nlocal VirtualUser = Services.VirtualUser\nlocal UserInputService = Services.UserInputService\nlocal Lighting = Services.Lighting\nlocal TweenService = Services.TweenService\nlocal Workspace = Services.Workspace\nlocal Camera = Services.Camera\n\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ===== GAME DATA =====\nruntimeEnv.NexusStage("waiting for game data (Events/MainGui/Info/Data)")\nlocal Events = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Events", 30)\nif not Events then return end\nlocal StartBossFight = Events:FindFirstChild("StartBossFight")\nlocal BossPhase2Action = Events:FindFirstChild("BossPhase2Action")\nlocal MainGui = runtimeEnv.NexusNeedChild(LocalPlayer:WaitForChild("PlayerGui", 30), "MainGui", 30)\nif not MainGui then return end\nlocal Info = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Info", 30)\nif not Info then return end\nlocal Data = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Data", 30)\nif not Data then return end\n\nfor _, v in pairs(LocalPlayer:WaitForChild("PlayerGui"):GetChildren()) do\n    if v.Name:find("MobileToggle") then v:Destroy() end\nend\npcall(function()\n    for _, v in pairs(game:GetService("CoreGui"):GetChildren()) do\n        if v.Name:find("MobileToggle") then v:Destroy() end\n    end\nend)\n\nlocal CODES = {\n    "BigUPD", "23MVisits", "24MVisits", "25MVisits", "26MVisits",\n    "42KLikes", "43KLikes", "44KLikes", "45KLikes", "UIBUG",\n    "33MVisits", "31MVisits", "32MVisits"\n}\n\n-- ============================================================\n-- ===== STATE TABLE =====\n-- ============================================================\nlocal NexusState = {\n    Fishing = {\n        Flags = {\n            MainFarm = true,\n            AutoCast = false,\n            AutoSkill = false,\n            SelectedSkills = { "Z", "X", "C", "V" },\n            SkillMode = "Spam",\n            SkillSequence = "Z,X,C,V",\n            SkillDelay = 0.3,\n            AutoFarmBoss = false,\n            AutoFarmSecretBoss = false,\n            AnchorLock = false,\n            AntiAFK = false,\n            AutoSkillCheck = false,\n            BossFightMode = "Normal",\n            BossFightThread = nil,\n            AutoFightEnzo = false,\n            AutoFightLongDiaohai = false,\n            AutoLongDiaohai = false,\n            LongDiaohaiFightMode = "Normal",\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        },\n        BossFarm = {\n            CurrentTarget = nil,\n            CurrentType = nil,\n            CurrentToken = nil,\n            CurrentRunId = 0,\n            HasHooked = false,\n            PendingCancel = false,\n            LastCast = 0,\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        }\n    },\n    MiscFlags = {\n        FlyMode = false,\n        Noclip = false,\n        InfiniteJump = false,\n        WalkOnWater = false,\n        FullBright = false,\n        AutoSell = false,\n        AutoBuy = false,\n        AutoEquipBait = false,\n        AutoEquipRod = false,\n    },\n    islands = {\n        {name = "Island 1", cframe = CFrame.new(-297, 9, 12), power = 0},\n        {name = "Island 2", cframe = CFrame.new(-1274, 21, -270), power = 17},\n        {name = "Island 3", cframe = CFrame.new(57, 9, 1115), power = 28},\n        {name = "Island 4", cframe = CFrame.new(-1343, 9, 1083), power = 35},\n        {name = "Island 5", cframe = CFrame.new(-12, 9, -1696), power = 45},\n        {name = "Island 6", cframe = CFrame.new(-1184, 20, -1652), power = 55},\n        {name = "Island 7", cframe = CFrame.new(1470, 9, -1685), power = 62},\n        {name = "Island 8", cframe = CFrame.new(1130, 9, 1364), power = 72},\n        {name = "Island 9", cframe = CFrame.new(1459, 8, -248), power = 90},\n        {name = "Island 10", cframe = CFrame.new(3028, 16, -124), power = 100},\n        -- Island 11 (if u have ego and tiger): chi duoc recommend khi co ca rod Ego va Tiger\n        {name = "Island 11", c               local targetTrait = selectedTargetTrait\n                if not skillName or skillName == "" or skillName == "No skill owned" then\n                    NexusLib:Notify({ Title = "Reroll", Message = "Select a valid skill", Duration = 2 })\n                    return\n                end\n                if not targetTrait or targetTrait == "" or targetTrait == "No trait available" then\n                    NexusLib:Notify({ Title = "Reroll", Message = "Select a target trait", Duration = 2 })\n                    return\n                end\n                if not RerollTrait then\n                    NexusLib:Notify({ Title = "Reroll", Message = "RerollTrait event not found", Duration = 2 })\n                    return\n                end\n                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                local rerollCount = p and p:FindFirstChild("Trait Reroll")\n                if rerollCount and rerollCount.Value <= 0 then\n                    NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left!", Duration = 2 })\n                    return\n                end\n\n                NexusState.Reroll.teleported = false\n                NexusState.Reroll.oldPosition = nil\n                if NexusState.Reroll.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local func = npc:FindFirstChild("Function")\n                        if func then\n                            local nanjiang = func:FindFirstChild("Nanjiang")\n                            if typeof(nanjiang) == "Instance" and nanjiang:IsA("Model") then\n                                local hrp = nanjiang:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.Reroll.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.Reroll.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.Reroll.teleported then\n                        NexusLib:Notify({ Title = "Reroll", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n\n                NexusState.Reroll.running = true\n                NexusLib:Notify({ Title = "Reroll", Message = "Reroll started... Target: " .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild("Trait Reroll")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left, stopping", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = "Reroll", Message = "Reroll failed, stopping", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = "Reroll", Message = "Got " .. targetTrait .. " on " .. skillName .. " after " .. successCount .. " rerolls!", Duration = 3 })\n                            break\n                        end\n                        task.wait(0.15)\n                    end\n\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild("HumanoidRootPart")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusState.Reroll.running = false\n                    NexusState.Reroll.thread = nil\n                    NexusLib:Notify({ Title = "Reroll", Message = "Stopped", Duration = 2 })\n                end)\n            end\n        })\n    end\n\n    -- Craft Bait\n    do\n        local CraftSection = ShopTab:CreateSection("Craft Bait")\n        Cfg.register(CraftSection:CreateTextbox(Cfg.wrap("Textbox", "Number of baits to craft", {\n            Name = "Number of baits to craft",\n            Placeholder = "1",\n            Default = "1",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })), "Textbox", "Number of baits to craft", {\n            Name = "Number of baits to craft",\n            Placeholder = "1",\n            Default = "1",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose a Bait", {\n            Name = "Choose a Bait",\n            Options = {"Rainbow Bait", "Frost Bait", "Nameless Bait"},\n            Default = "Rainbow Bait",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })), "Dropdown", "Choose a Bait", {\n            Name = "Choose a Bait",\n            Options = {"Rainbow Bait", "Frost Bait", "Nameless Bait"},\n            Default = "Rainbow Bait",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap("Dropdown", "Craft Method", {\n            Name = "Craft Method",\n            Options = {"Instant", "Teleport"},\n            Default = "Instant",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })), "Dropdown", "Craft Method", {\n            Name = "Craft Method",\n            Options = {"Instant", "Teleport"},\n            Default = "Instant",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })\n\n        local BAIT_RECIPES = {\n            ["Rainbow Bait"] = {\n                {name = "Colossal Tigerfish", minKg = 3000000, maxKg = 6000000},\n                {name = "Heavenpiercer Turtle", minKg = 3000000, maxKg = 6000000},\n                {name = "Golden Guardian Fish", minKg = 1000000, maxKg = 3000000},\n                {name = "Crimson Electric Eel", minKg = 3000000, maxKg = 4000000},\n            },\n            ["Frost Bait"] = {\n                {name = "Frost Kingfish", minKg = 4000000, maxKg = 7000000},\n                {name = "Ascended Perch", minKg = 900000, maxKg = 1000000},\n                {name = "Primordial Kunfish Overlord", minKg = 1000000, maxKg = 1600000},\n                {name = "Warbringer Shark", minKg = 500000, maxKg = 800000},\n            },\n            ["Nameless Bait"] = {\n                {name = "Mountain Fish", minKg = 1000000, maxKg = 5000000},\n                {name = "Tiger Mirefish", minKg = 1000000, maxKg = 3000000},\n                {name = "Mirage Lanternfish", minKg = 3000000, maxKg = 5000000},\n                {name = "Octoparasitic Fish", minKg = 3000000, maxKg = 5000000},\n            }\n        }\n\n        local function checkMaterials(baitName, quantity)\n            local recipe = BAIT_RECIPES[baitName]\n            if not recipe then return false, "No recipe found for " .. baitName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, "Player data not found" end\n            local inventory = userData:FindFirstChild("Inventory")\n            if not inventory then return false, "Inventory not found" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= "" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < quantity then\n                    table.insert(missing, req.name .. " (can " .. quantity .. ", co " .. count .. ")")\n                end\n            end\n            if #missing > 0 then\n                return false, "Missing materials: " .. table.concat(missing, ", ")\n            end\n            return true, "Materials are sufficient!"\n        end\n\n        local function craftBait()\n            local qty = NexusState.craftBaitQuantity\n            local ok, msg = checkMaterials(NexusState.craftBaitName, qty)\n            if not ok then\n                NexusLib:Notify({ Title = "Craft Bait", Message = msg, Duration = 4 })\n                return\n            end\n            local method = NexusState.craftBaitMethod or "Instant"\n            local teleported = false\n            if method == "Teleport" then\n                local npc = Workspace:FindFirstChild("NPC")\n                if npc then\n                    local buyBait = npc:FindFirstChild("BuyBait")\n                    if buyBait then\n                        local children = buyBait:GetChildren()\n                        if #children >= 5 then\n                            local targetModel = children[5]\n                            if typeof(targetModel) == "Instance" and targetModel:IsA("Model") then\n                                local hrp = targetModel:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root the or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == "Easy Quest" then\n                                        selAction = "EasyAcceptQuest"\n                                    else\n                                        selAction = "HardAcceptQuest"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = "Quest",\n                                            Message = "Claimed " .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })\n                end\n            end\n        })), "Toggle", "Auto Claim Ticket Quest (Fast)", {\n            Name = "Auto Claim Ticket Quest (Fast)",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == "Easy Quest" then\n                                        selAction = "EasyAcceptQuest"\n                                    else\n                                        selAction = "HardAcceptQuest"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = "Quest",\n                                            Message = "Claimed " .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = "Quest", Message = "Claim failed 5 times. Check NPC or quest type.", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = "Quest", Message = "Auto claim stopped", Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- ===== AUTO DO TICKET QUEST =====\n    local DoSection = QuestsTab:CreateSection("Auto Do Ticket Quest")\n    -- Store the dynamic controls\n    local islandModeDropdown = nil\n    local islandDropdown = nil\n    local islandDropdownFrame = nil\n    local selectedIslandMode = "Auto Select Island"\n    local selectedIslandName = "Island 1"\n    local islandList = {"Island 1", "Island 2", "Island 3", "Island 4", "Island 5",\n                        "Island 6", "Island 7", "Island 8", "Island 9", "Island 10", "Island 11", "Island 12", "Island 13"}\n\n    -- Remove the island dropdown (if present)\n    local function clearIslandDropdown()\n        if islandDropdownFrame and islandDropdownFrame._frame then\n            pcall(function()\n                if type(islandDropdownFrame.Destroy) == "function" then\n                    islandDropdownFrame:Destroy()\n                elseif islandDropdownFrame._frame and type(islandDropdownFrame._frame.Destroy) == "function" then\n                    islandDropdownFrame._frame:Destroy()\n                end\n            end)\n        end\n        islandDropdownFrame = nil\n        islandDropdown = nil\n    end\n\n    -- Create the island dropdown\n    -- NOTE: picking an island forces manual mode, so Auto Do Ticket\n    -- never pulls the player back to the recommended island.\n    local function createIslandDropdown()\n        clearIslandDropdown()\n        islandDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose an island", {\n            Name = "Choose an island",\n            Options = islandList,\n            Default = selectedIslandName,\n            Callback = function(value)\n                selectedIslandName = value\n                selectedIslandMode = "Choose Island Manual"\n                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set("Choose Island Manual") end end)\n            end\n        })), "Dropdown", "Choose an island", {\n            Name = "Choose an island",\n            Options = islandList,\n            Default = selectedIslandName,\n            Callback = function(value)\n                selectedIslandName = value\n                selectedIslandMode = "Choose Island Manual"\n                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set("Choose Island Manual") end end)\n            end\n        })\n        islandDropdownFrame = islandDropdown\n    end\n\n    -- Create the mode dropdown\n    local modeDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap("Dropdown", "Island Selection Mode", {\n        Name = "Island Selection Mode",\n        Options = {"Auto Select Island", "Choose Island Manual"},\n        Default = "Auto Select Island",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == "Choose Island Manual" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })), "Dropdown", "Island Selection Mode", {\n        Name = "Island Selection Mode",\n        Options = {"Auto Select Island", "Choose Island Manual"},\n        Default = "Auto Select Island",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == "Choose Island Manual" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })\n\n    -- Create the default island dropdown (hidden, shown only in manual mode)\n    -- Not built up front, only once manual is picked\n\n    -- ===== Target island resolver =====\n    local function getTargetIsland()\n        if selectedIslandMode == "Auto Select Island" then\n            return getRecommendedIsland()\n        else\n            for _, island in ipairs(NexusState.islands) do\n                if island.name == selectedIslandName then\n                    return island\n                end\n            end\n            return nil\n        end\n    end\n\n\n    local function parseQuestString(str)\n        if not str or str == "" then return nil, nil end\n        local parts = {}\n        for part in string.gmatch(str, "[^,]+") do table.insert(parts, part) end\n        if #parts >= 3 then\n            local target = nil\n            local typ = nil\n            if string.find(parts[1], "Boss") then\n                target = tonumber(parts[3])\n                typ = parts[1]\n            else\n                target = tonumber(parts[2])\n                typ = parts[3]\n            end\n            if target and typ then return target, typ end\n        end\n        return nil, nil\n    end\n\n    local function getCurrentQuestProgress()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return nil end\n        local quest = userData:FindFirstChild("Quest")\n        if not quest then return nil end\n        local main = quest:FindFirstChild("Main")\n        if not main then return nil end\n        for _, folder in pairs(main:GetChildren()) do\n            if typeof(folder) == "Instance" and typeof(folder) == "Instance" and folder:IsA("Folder") and (folder.Name == "Easy Ticket Quest" or folder.Name == "Hard Ticket Quest") then\n                local current = nil\n                local target = nil\n                local typ = nil\n                local questName = folder.Name\n                for _, child in pairs(folder:GetChildren()) do\n                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") or child:IsA("IntValue") then\n                        if child.Name == "1" then\n                            current = child.Value\n                        end\n                    end\n                end\n                local objective = folder:FindFirstChild("Objective")\n                if objective then\n                    for _, child in pairs(objective:GetChildren()) do\n                        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("StringValue") and child.Name == "1" then\n                            local val = child.Value\n                            if val and val ~= "" then\n                                NexusState.ticketObjectiveText = tostring(val)\n                                local t, ty = parseQuestString(val)\n                                if t and ty then\n                                    target = t\n                                    typ = ty\n                                end\n                            end\n                        end\n                    end\n                end\n                if current and target and typ then\n                    return current, target, questName, typ\n                end\n            end\n        end\n        return nil\n    end\n\n    local function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress(hile task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild("EquippedBait")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or ""\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = "Auto Equip", Message = "Equipped best bait: " .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = "Nameless Octoparasite"\n        local RHY_LANES = { "A", "S", "D" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = "Safe",\n            RiskRate = 25,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            RiskThread = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild("Ocean")\n            if ocean then\n                local boss = ocean:FindFirstChild("Boss")\n                if boss then\n                    local fn = boss:FindFirstChild("FishName")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild("Fishes")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("BasePart") then return inst.CFrame end\n                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("Model") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA("BasePart", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = "Nameless", Message = "Cannot find " .. NAMELESS_NAME .. " in Workspace (boss not spawned yet?)", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = "Nameless", Message = "Found boss but could not get its position!", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = "Nameless", Message = "Character not found!", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = "Nameless", Message = "Teleported to " .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild("Button")\n                    if not btn then return false end\n                    if not (typeof(btn) == "Instance" and (btn:IsA("TextButton") or btn:IsA("ImageButton"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService("VirtualInputManager")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService("VirtualInputManager")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n                if ok and res then return true end\n                Rhy.Method = nil\n            end\n            for i, fn in ipairs(methods) do\n                local ok, res = pcall(fn)\n                if ok and res then\n                    Rhy.Method = i\n                    return true\n                end\n            end\n            return false\n        end\n\n        local function rhyGui()\n            local fishing = MainGui and MainGui:FindFirstChild("Fishing")\n            if not fishing then return nil, nil end\n            return fishing:FindFirstChild("Rhythm"), fishing\n        end\n\n        local function rhyUiActive()\n            local gui, fishing = rhyGui()\n            if not gui or not fishing then return false end\n            return gui.Visible == true and fishing.Visible == true\n        end\n\n        local function rhyMaxBand()\n            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02\n            if m < 0.01 then m = 0.01 end\n            return m\n        end\n\n        local function rhyScan(now)\n            local gui = rhyGui()\n            if not gui then return end\n            for _, lane in ipairs(RHY_LANES) do\n                local laneFrame = gui:FindFirstChild("Progression" .. lane)\n                if laneFrame then\n                    local barY = RHY_BAR_FALLBACK\n                    local barFrame = laneFrame:FindFirstChild("BarFrame")\n                    if barFrame then\n                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)\n                        if okB and type(y) == "number" then barY = y end\n                    end\n                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())\n                    local inWindow = 0\n                    for _, note in ipairs(laneFrame:GetChildren()) do\n                        if note.Name == "Note_FX" then\n                            local okP, y = pcall(function() return note.Position.Y.Scale end)\n                            if okP and type(y) == "number" then\n                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then\n                                    inWindow = inWindow + 1\n                                end\n                            end\n                        end\n                    end\n                    if inWindow > 5 then inWindow = 5 end\n                    for _ = 1, inWindow do\n                        if rhyPress(laneFrame, lane) then\n                            Rhy.Stats.hit = Rhy.Stats.hit + 1\n                        end\n                    end\n                end\n            end\n        end\n\n        local function rhyStartRisk()\n            if Rhy.RiskThread then return end\n            Rhy.RiskThread = task.spawn(function()\n                while alive() and Rhy.Enabled and Rhy.Mode == "Risk" and Rhy.Active do\n                    local rate = math.clamp(tonumber(Rhy.RiskRate) or 25, 1, 200)\n                    local burst = math.max(1, math.floor(rate / 20))\n                    for _ = 1, burst do\n                        pcall(function() Events.RhythmHit:FireServer("hit") end)\n                        Rhy.Stats.spam = Rhy.Stats.spam + 1\n                    end\n                    task.wait(burst / rate)\n                end\n                Rhy.RiskThread = nil\n            end)\n        end\n\n        if runtimeEnv.NexusRhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end\n        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end\n        if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end\n        if runtimeEnv.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end\n        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end\n\n        pcall(function()\n            local evStart = Events:FindFirstChild("RhythmStart")\n            if evStart then\n                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)\n                    if not alive() then return end\n                    Rhy.Config = cfg\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    Rhy.Stats = { hit = 0, spam = 0 }\n                    Rhy.NextPress = {}\n                    if Rhy.Enabled then\n                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)\n                        NexusLib:Notify({\n                            Title = "Auto Nameless",\n                            Message = "Nameless started [" .. tostring(Rhy.Mode) .. "]" .. (hp and (" | HP " .. tostring(hp)) or ""),\n                            Duration = 3,\n                        })\n                        if Rhy.Mode == "Risk" then rhyStartRisk() end\n                    end\n                end)\n            end\n            local evStop = Events:FindFirstChild("RhythmStop")\n            if evStop then\n                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                end)\n            end\n        end)\n\n        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().\n        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.\n        pcall(function()\n            local evBGM = Events:FindFirstChild("BossPhaseBGM")\n            if evBGM then\n                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)\n                    if not alive() then return end\n                    if bossName ~= nil and tostring(bossName) ~= "Nameless Octoparasite" then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless boss signal [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })\n                    end\n                end)\n            end\n            local evP2 = Events:FindFirstChild("BossPhase2S            local hrp = sofa:FindFirstChild("HumanoidRootPart")\n            if hrp then return hrp.Position end\n            local primary = sofa.PrimaryPart\n            if primary then return primary.Position end\n            for _, part in ipairs(sofa:GetDescendants()) do\n                if typeof(part) == "Instance" and part:IsA("BasePart") then\n                    return part.Position\n                end\n            end\n        end\n        return nil\n    end\n\n    local function teleportToSofa()\n        local pos = getSofaPosition()\n        if not pos then return false end\n        local char = LocalPlayer.Character\n        if not char then return false end\n        local hrp = char:FindFirstChild("HumanoidRootPart")\n        if not hrp then return false end\n        NexusState.lastPosition = hrp.Position\n        hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))\n        return true\n    end\n\n    local function teleportBack()\n        if not NexusState.lastPosition then return end\n        local char = LocalPlayer.Character\n        if not char then return end\n        local hrp = char:FindFirstChild("HumanoidRootPart")\n        if not hrp then return end\n        safeTeleport(hrp, CFrame.new(NexusState.lastPosition))\n        NexusState.lastPosition = nil\n    end\n\n    local function doSell()\n        if not MiscFlags.AutoSell then return end\n        if tick() - (NexusState.sellCooldown or 0) < 0.5 then return end\n        NexusState.sellCooldown = tick()\n        local method1 = NexusState.sellMethod1 or "Spam"\n        local method2 = NexusState.sellMethod2 or "Instant"\n        if method1 == "When full" then\n            local count = getInventoryCount()\n            local limit = getInventoryLimit()\n            if limit == 0 then return end\n            if count < limit - 3 then return end\n        end\n        local teleported = false\n        if method2 == "Teleport" then\n            teleported = teleportToSofa()\n            if teleported then task.wait(0.3) end\n        end\n        pcall(function() Events.SellFish:FireServer("All") end)\n        if teleported then\n            task.wait(0.2)\n            teleportBack()\n        end\n    end\n\n    task.spawn(function()\n        while task.wait(2) do\n            if not alive() then break end\n            pcall(doSell)\n        end\n    end)\nend\n\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) end\nruntimeEnv.NexusMinigameConn = Events.FishingMinigame.OnClientEvent:Connect(function(p1, p2, p3)\n    if not p1 or not p2 then return end\n    Fishing.BossFarm.CurrentTarget = p1\n    Fishing.BossFarm.CurrentToken = p3\n    Fishing.BossFarm.HasHooked = true\n    Fishing.BossFarm.PendingCancel = false\n    Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n    local runId = Fishing.BossFarm.CurrentRunId\n    local target = getCurrentHookTarget()\n    local shouldFarm = shouldFarmBossTarget(target)\n    if bossFarmEnabled() and not shouldFarm then\n        Fishing.BossFarm.PendingCancel = true\n        task.delay(0.15, cancelOrReleaseNormalFish)\n        return\n    end\n    if Fishing.Flags.AutoCast or (bossFarmEnabled() and shouldFarm) then\n        task.spawn(function()\n            local minigameActive = true\n            local connection\n            local fishingGui = MainGui:FindFirstChild("Fishing")\n            if fishingGui then\n                connection = fishingGui:GetPropertyChangedSignal("Visible"):Connect(function()\n                    if not fishingGui.Visible then\n                        minigameActive = false\n                        if connection then connection:Disconnect() connection = nil end\n                    end\n                end)\n            end\n            while minigameActive do\n                if not alive() then break end\n                if not MainGui:FindFirstChild("Fishing") or not MainGui.Fishing.Visible then break end\n                if bossFarmEnabled() then\n                    if runId ~= Fishing.BossFarm.CurrentRunId then break end\n                    target = getCurrentHookTarget()\n                    shouldFarm = shouldFarmBossTarget(target)\n                    if not shouldFarm then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                        break\n                    end\n                    farmHookedBoss(target)\n                    task.wait(0.08)\n                else\n                    pcall(function() Events.UpdateFishProgression:FireServer() end)\n                    task.wait(0.2)\n                end\n            end\n            if connection then pcall(function() connection:Disconnect() end) connection = nil end\n            if bossFarmEnabled() and runId == Fishing.BossFarm.CurrentRunId then\n                resetBossFarmTarget()\n            end\n        end)\n    end\nend)\n\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) end\nruntimeEnv.NexusSlamConn = Events.Slam.OnClientEvent:Connect(function(cb)\n    if Fishing.Flags.MainFarm then\n        task.spawn(function()\n            task.wait(0.1)\n            pcall(function() cb:FireServer("Perfect") end)\n            local tc = MainGui:FindFirstChild("Fishing") and MainGui.Fishing:FindFirstChild("TrashCan")\n            if tc and tc:FindFirstChild("Slam") then tc.Slam:Destroy() end\n        end)\n    end\nend)\n\n-- GUI click QTE (Rewritten Auto Enzo)\nlocal prevBarPos = 0\nlocal lastFrameTime = tick()\nlocal currentSpeed = 0\nlocal lastQTEClick = 0\nlocal lastQTEHitboxX = nil\n\n-- Click QTE the same way the game listens: desktop Fishing GUI button\n-- first (Fishing2.MouseButton1Down path), then mobile button, then\n-- synthetic mouse input as last fallback. Never fires blind.\nlocal EnzoQTEGui = nil\nlocal function findEnzoQTEGui()\n    if EnzoQTEGui and EnzoQTEGui.Parent then return EnzoQTEGui end\n    EnzoQTEGui = nil\n    local fishing = MainGui:FindFirstChild("Fishing")\n    local btn = fishing and (fishing:FindFirstChild("Fishing2") or fishing:FindFirstChild("Button"))\n    if btn and typeof(btn) == "Instance" and btn:IsA("GuiButton") then EnzoQTEGui = btn return btn end\n    local mobileFishing = MainGui:FindFirstChild("Mobile") and MainGui.Mobile:FindFirstChild("Fishing")\n    local mbtn = mobileFishing and (mobileFishing:FindFirstChild("Button") or mobileFishing)\n    if mbtn and typeof(mbtn) == "Instance" and mbtn:IsA("GuiButton") then EnzoQTEGui = mbtn return mbtn end\n    if fishing and typeof(fishing) == "Instance" and fishing:IsA("GuiButton") then EnzoQTEGui = fishing return fishing end\n    return nil\nend\n\nlocal function pressEnzoQTE()\n    local btn = findEnzoQTEGui()\n    if btn and firesignal then\n        pcall(firesignal, btn.MouseButton1Down)\n        return\n    end\n    pcall(function()\n        local vim = game:GetService("VirtualInputManager")\n        vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)\n        vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)\n    end)\nend\n\nlocal renderAccum = 0\nlocal RENDER_THROTTLE = 0.033\nlocal cachedFishingGui = nil\nlocal cachedBossBar = nil\n\nlocal function updateFrameLogic(dt)\n    if not cachedFishingGui or not cachedFishingGui.Parent then\n        cachedFishingGui = MainGui and MainGui:FindFirstChild("Fishing")\n        cachedBossBar = cachedFishingGui and cachedFishingGui:FindFirstChild("BossFightBar")\n    end\n    local fishing = cachedFishingGui\n    local bossBar = cachedBossBar\n    local bossBarVisible = bossBar ~= nil and bossBar.Visible == true\n    local fishingVisible = fishing ~= nil and fishing.Visible == true\n\n    if not bossBarVisible then\n        renderAccum = renderAccum + dt\n        if renderAccum < RENDER_THROTTLE then return end\n        renderAccum = 0\n    end\n\n    if (Fishing.Flags.AnchorLock or Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and fishingVisible then\n        if Fishing.Flags.AnchorLock and not bossBarVisible and not Fishing.BossFarm.PendingCancel then\n            local bf = fishing:FindFirstChild("BarFrame")\n            local b = bf and bf:FindFirstChild("Bar")\n            if b then b.Position = UDim2.new(0.5, 0, 0.5, 0) end\n        end\n\n        if (Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and bossBarVisible then\n            local bar = bossBar:FindFirstChild("Bar")\n            local hitbox = bossBar:FindFirstChild("Hitbox")\n            local badHitbox = bossBar:FindFirstChild("HitboxBad")\n            if bar and hitbox and hitbox.Visible then\n                local barPos = bar.Position.X.Scale\n                local hbPos = hitbox.Position.X.Scale - hitbox.Size.X.Scale * hitbox.AnchorPoint.X\n                local hbSize = hitbox.Size.X.Scale\n                if lastQTEHitboxX ~= hbPos then\n                    lastQTEHitboxX = hbPos\n                    lastQTEClick = 0\n                end\n\n                local now = tick()\n                local dtFrame = now - lastFrameTime\n                lastFrameTime = now\n\n                if dtFrame > 0.001 and dtFrame < 0.1 then\n                    local rawSpeed = (barPos - prevBarPos) / dtFrame\n                    prevBarPos = barPos\n                    if math.abs(rawSpeed) < 5 then\n                        currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3\n                    end\n                else\n                    prevBarPos = barPos\n                end\n\n                local lastInput = UserInputService:GetLastInputType()\n                local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025\n                local compensatedBarPos = barPos - (currentSpeed * latency)\n\n                local margin = hbSize * 0.15\n                local badOverlap = false\n                if badHitbox and badHitbox.Visible then\n                    local badLeft = badHitbox.Position.X.Scale - badHitbox.Size.X.Scale * badHitbox.AnchorPoint.X\n                    badOverlap = compensatedBarPos >= badLeft and compensatedBarPos <= badLeft + badHitbox.Size.X.Scale\n                end\n\n                if not badOverlap and compensatedBarPos >= hbPos + margin and compensatedBarPos <= hbPos + hbSize - margin then\n                    if tick() - lastQTEClick > 0.15 then\n                        lastQTEClick = tick()\n                        pressEnzoQTE()\n                    end\n                end\n            else\n                lastQTEHitboxX = nil\n                prevBarPos = 0\n                lastFrameTime = tick()\n                currentSpeed = 0\n            end\n        else\n            lastQTEHitboxX = nil\n            prevBarPos = 0\n            lastFrameTime = tick()\n            currentSpeed = 0\n        end\n    end\n\n    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then\n        local h = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n        local hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")\n        if h and hum then\n            local cameraLook = Camera.CFrame.LookVector\n            local move = hum.MoveDirection\n            local horizontal = Vector3.new(move.X, 0, move.Z)\n            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)\n            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)\n            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)\n            if look.Magnitude > 0.01 then\n                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)\n            end\n        end\n    end\n\n    if MiscFlags.FullBright then\n        if not NexusState.fullBrightApplied then\n            Lighting.Ambient = Color3.new(1,1,1)\n            Lighting.ColorShift_Bottom = Color3.new(1,1,1)\n            Lighting.C  local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            applyLanguageToGui(pg:FindFirstChild("NexusPanel"))\n            applyLanguageToGui(pg:FindFirstChild("NexusNotifications"))\n        end\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                applyLanguageToGui(cg:FindFirstChild("NexusPanel"))\n                applyLanguageToGui(cg:FindFirstChild("NexusNotifications"))\n            end\n        end)\n    end\n\n    function I18n.initListeners()\n        local function hookGui(gui)\n            if not gui then return end\n            gui.DescendantAdded:Connect(function(desc)\n                task.wait(0.03)\n                translateObject(desc)\n            end)\n        end\n\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            local panel = pg:FindFirstChild("NexusPanel")\n            if panel then hookGui(panel) end\n            local notifs = pg:FindFirstChild("NexusNotifications")\n            if notifs then hookGui(notifs) end\n\n            pg.ChildAdded:Connect(function(child)\n                if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then\n                    hookGui(child)\n                    task.wait(0.1)\n                    applyLanguageToGui(child)\n                end\n            end)\n        end\n\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                local panel = cg:FindFirstChild("NexusPanel")\n                if panel then hookGui(panel) end\n                local notifs = cg:FindFirstChild("NexusNotifications")\n                if notifs then hookGui(notifs) end\n\n                cg.ChildAdded:Connect(function(child)\n                    if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then\n                        hookGui(child)\n                        task.wait(0.1)\n                        applyLanguageToGui(child)\n                    end\n                end)\n            end\n        end)\n    end\nend\n\n-- ===== FAKE NAME (STREAMER MODE) CORE =====\n-- ============================================================\ndo\n    local realName = LocalPlayer.Name\n    local realDisplayName = LocalPlayer.DisplayName\n    local fakeNameConn = nil\n    local fakeNameThread = nil\n    local maskIdsInText -- forward declare (dinh nghia ben duoi)\n\n    local function replacePlain(text, find, repl)\n        if find == "" then return text end\n        local parts = {}\n        local start = 1\n        while true do\n            local s, e = string.find(text, find, start, true)\n            if not s then\n                table.insert(parts, string.sub(text, start))\n                break\n            end\n            table.insert(parts, string.sub(text, start, s - 1))\n            table.insert(parts, repl)\n            start = e + 1\n        end\n        return table.concat(parts)\n    end\n\n    local function replaceTextInObject(obj)\n        if not NexusState.fakeNameEnabled then return end\n        if not obj or typeof(obj) ~= "Instance" then return end\n        pcall(function()\n            if typeof(obj) == "Instance" and typeof(obj) == "Instance" and obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then\n                local text = obj.Text\n                if text and #text > 0 then\n                    local updated = false\n                    if realDisplayName ~= "" and string.find(text, realDisplayName, 1, true) then\n                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or "NexusPlayer")\n                        updated = true\n                    end\n                    if realName ~= "" and string.find(text, realName, 1, true) then\n                        text = replacePlain(text, realName, NexusState.fakeName or "NexusPlayer")\n                        updated = true\n                    end\n                    -- Guild display: doi ten guild that -> fake guild de khong bi ban\n                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then\n                        local rg = tostring(NexusState.realGuildName)\n                        if rg ~= "ZION" and not string.find(text, "ZION", 1, true) and string.find(text, rg, 1, true) then\n                            text = replacePlain(text, rg, NexusState.fakeGuildName or "NexusGuild")\n                            updated = true\n                        end\n                    end\n                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten\n                    if maskIdsInText then\n                        local masked, idChanged = maskIdsInText(text)\n                        if idChanged then\n                            text = masked\n                            updated = true\n                        end\n                    end\n                    if updated then\n                        obj.Text = text\n                    end\n                end\n            end\n        end)\n    end\n\n    -- Che ID: doi ten khong thoi van bi report vi nguoi ta doc UserId / PlaceId /\n    -- JobId tren man hinh (hoac trong anh chup). Nen phai che luon cac ID nay.\n    local realUserId = tostring(LocalPlayer.UserId)\n    local realPlaceId = tostring(game.PlaceId)\n\n    function maskIdsInText(text)\n        if not NexusState.fakeNameEnabled then return text, false end\n        local changed = false\n        if #realUserId >= 5 and string.find(text, realUserId, 1, true) then\n            if (NexusState.fakeIdMode or 1) == 2 then\n                text = string.gsub(text, realUserId, "****")\n            else\n                text = string.gsub(text, realUserId, tostring(NexusState.fakeUserId or "0"))\n            end\n            changed = true\n        end\n        if #realPlaceId >= 5 and string.find(text, realPlaceId, 1, true) then\n            text = string.gsub(text, realPlaceId, "0000000000")\n            changed = true\n        end\n        local guidPat = "%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x"\n        if string.find(text, guidPat) then\n            text = string.gsub(text, guidPat, "********-****-****-****-************")\n            changed = true\n        end\n        return text, changed\n    end\n\n    local function applyFakeNameToAll()\n        if not NexusState.fakeNameEnabled then return end\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            for _, v in ipairs(pg:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                for _, v in ipairs(cg:GetDescendants()) do\n                    replaceTextInObject(v)\n                end\n            end\n        end)\n    end\n\n    function NexusState.enableFakeName()\n        if NexusState.fakeNameEnabled then return end\n        NexusState.fakeNameEnabled = true\n        applyFakeNameToAll()\n\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            fakeNameConn = pg.DescendantAdded:Connect(function(desc)\n                if NexusState.fakeNameEnabled then\n                    task.wait(0.05)\n                    replaceTextInObject(desc)\n                end\n            end)\n        end\n\n        fakeNameThread = task.spawn(function()\n            while NexusState.fakeNameEnabled do\n                pcall(applyFakeNameToAll)\n                task.wait(1.5)\n            end\n        end)\n        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name active: " .. tostring(NexusState.fakeName), Duration = 2 })\n    end\n\n    function NexusState.disableFakeName()\n        NexusState.fakeNameEnabled = false\n        if fakeNameConn then fakeNameConn:Disconnect(); fakeNameConn = nil end\n        if fakeNameThread then task.cancel(fakeNameThread); fakeNameThread = nil end\n        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name disabled", Duration = 2 })\n    end\nend\n\n-- ============================================================\n-- Chong "cau tren troi": khi dang bay / vua teleport, player lo lung tren khong\n-- nen phao khong roi trung nuoc -> cast phi hoai. Raycast xuong kiem tra nuoc.\nfunction NexusState.isOverWater()\n    local ok, result = pcall(function()\n        local char = LocalPlayer.Character\n        local root = char and char:FindFirstChild("HumanoidRootPart")\n        if not root then return false end\n\n        local params = RaycastParams.new()\n        params.FilterType = Enum.RaycastFilterType.Exclude\n        params.FilterDescendantsInstances = { char }\n        params.IgnoreWater = false\n\n        local hit = Workspace:Raycast(root.Position, Vector3.new(0, -200, 0), params)\n        if not hit then return false end\n\n        if hit.Instance == Workspace.Terrain and hit.Material == Enum.Material.Water then\n            return true\n        end\n        local n = string.lower(hit.Instance.Name)\n        if string.find(n, "water") or string.find(n, "ocean") or string.find(n, "sea") then\n            return true\n        end\n        return false\n    end)\n    if not ok then return true end -- loi thi cho cast, khong chan oan\n    return result\nend\n\nfunction NexusState.canCastNow()\n    if NexusState.flying then return false end\n    -- Khi bat auto cast / farm boss / farm secret: tele len troi la chu y\n    -- (chong detect), vay isOverWater se false -> bo qua kiem tra nuoc,\n    -- chi chan khi dang fly thu cong.\n    local F = NexusState.Fishing and NexusState.Fishing.Flags\n    if F and (F.AutoCast or F.AutoFarmBoss or F.AutoFarmSecretBoss) then\n        return true\n    end\n    return NexusState.isOverWater()\nend\n\n-- ===== UNIVERSAL BAIT MERCHANT LOCATOR =====\n-- ============================================================\nlocal function findBaitMerchantHRP()\n    local char = LocalPlayer.Character\n    local root = char and char:FindFirstChild("HumanoidRootPart")\n    local myPos = root and root.Position or Vector3.new(0, 0, 0)\n    local bestHRP = nil\n    local bestDist = math.huge\n\n    pcall(function()\n        local npcFolder = Workspace:FindFirstChild("NPC")\n        if npcFolder then\n            local bb = npcFolder:FindFirstChild("BuyBait")\n            if bb then\n                for _, model in ipairs(bb:GetChildren()) do\n                    if typeof(model) == "Instance" and typeof(model) == "Instance" and model:IsA("Model") then\n                        local hrp = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            local func = npcFolder:FindFirstChild("Function")\n            if func then\n                for _, model in ipairs(func:GetChildren()) do\n                    if typeof(model) == "Instance" and typeof